python3 - <<'PY'
import subprocess,json,sys
SHA="0ec4261ee4e134ed18834b2dca7943bf9808f950"
root="/home/admin1/server-core"
name="gace-server-core-bounded-host:cu40-"+SHA[:12]
try:
 p=subprocess.run(["git","-C",root,"rev-parse","HEAD"],capture_output=True,text=True,timeout=8)
 if p.stdout.strip()!=SHA:raise RuntimeError("HOST_SOURCE_MOVED")
 b=subprocess.run(["docker","build","--pull=false","-f","Dockerfile.bounded-host","-t",name,root],capture_output=True,text=True,timeout=72)
 if b.returncode:raise RuntimeError("BOUNDED_IMAGE_BUILD_EXIT_"+str(b.returncode)+" tail="+b.stderr[-250:])
 i=subprocess.run(["docker","image","inspect","-f","{{.Id}}",name],capture_output=True,text=True,timeout=10)
 if i.returncode:raise RuntimeError("IMAGE_INSPECT_FAILED")
 info={"tag":"AGENT_POOL_IMAGE_BUILT","source_sha":SHA,"image":name,"image_id":i.stdout.strip(),"runtime_switched":False}
 g=subprocess.run(["gh","api","-X","POST","repos/G-ACE-inc/server-core/issues/40/comments","--input","-","--jq",".html_url"],input=json.dumps({"body":"AGENT_POOL_IMAGE_BUILT\n"+json.dumps(info,indent=2)}),capture_output=True,text=True,timeout=12)
 print("AGENT_POOL_IMAGE_BUILT="+json.dumps({**info,"recorded":g.returncode==0}))
except Exception as e:
 print("AGENT_POOL_IMAGE_BUILD_FAILED="+str(e)[:320])
 sys.exit(1)
PY
